import paramiko
c = paramiko.SSHClient()
c.set_missing_host_key_policy(paramiko.AutoAddPolicy())
c.connect('46.202.154.25', 22, 'root', '2N00py123+++')
# Update MainActivity with WebGL forcing
mainactivity = '''package com.ouroboros.arelorian;
import android.os.Build;
import android.os.Bundle;
import android.view.WindowManager;
import android.webkit.WebSettings;
import android.webkit.WebView;
import com.getcapacitor.BridgeActivity;
public class MainActivity extends BridgeActivity {
    @Override
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        // Force hardware acceleration
        getWindow().setFlags(
            WindowManager.LayoutParams.FLAG_HARDWARE_ACCELERATED,
            WindowManager.LayoutParams.FLAG_HARDWARE_ACCELERATED
        );
    }

    @Override
    public void onResume() {
        super.onResume();
        // Enable WebGL debugging in dev builds
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT) {
            WebView.setWebContentsDebuggingEnabled(true);
        }
    }
}
'''
sftp = c.open_sftp()
with sftp.file('/tmp/MainActivity.java', 'w') as f:
    f.write(mainactivity)
c.exec_command('cp /tmp/MainActivity.java /opt/areloria/client/android/app/src/main/java/com/ouroboros/arelorian/MainActivity.java')
print('MainActivity updated with WebGL support')
c.close()
